// Páginas públicas del sitio de 2 Amigos Aberturas que forman la base de conocimiento.
// Para sumar páginas nuevas (por ejemplo subcategorías de ventanas), agregalas acá.
const base = "https://2amigosaberturas.com.ar";
const paginas = [
  { path: "/",                                 categoria: "inicio" },
  { path: "/pages/catalogo/",                  categoria: "catalogo" },
  { path: "/pages/catalogo/puertas/",          categoria: "puertas" },
  { path: "/pages/catalogo/puertas/seguridad/",  categoria: "puertas-seguridad" },
  { path: "/pages/catalogo/puertas/exterior/",   categoria: "puertas-exterior" },
  { path: "/pages/catalogo/puertas/interior/",   categoria: "puertas-interior" },
  { path: "/pages/catalogo/puertas/pivotantes/", categoria: "puertas-pivotantes" },
  { path: "/pages/catalogo/puertas/cortafuego/", categoria: "puertas-cortafuego" },
  { path: "/pages/catalogo/ventanas/",         categoria: "ventanas" },
  { path: "/pages/catalogo/portones/",         categoria: "portones" },
  { path: "/pages/catalogo/rejas/",            categoria: "rejas" },
  { path: "/pages/catalogo/mosquiteros/",      categoria: "mosquiteros" },
  { path: "/pages/catalogo/cerramientos/",     categoria: "cerramientos" },
  { path: "/pages/nosotros/",                  categoria: "empresa" },
  { path: "/pages/contacto/",                  categoria: "contacto" }
];
return paginas.map(p => ({ json: { url: base + p.path, categoria: p.categoria } }));

// Convierte el HTML en texto limpio y decide si la página sirve para la base de conocimiento.
// Motivos de descarte: error de conexión, código HTTP de error, bloqueo anti-bot del hosting o poco texto.
const urls = $('URLs a indexar').all();
const salida = [];

$input.all().forEach((item, i) => {
  const origen = urls[i] ? urls[i].json : {};
  const status = item.json.statusCode ?? (item.json.error ? 0 : 200);
  let html = item.json.body ?? item.json.data ?? '';
  if (typeof html !== 'string') html = JSON.stringify(html);

  const t = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  const titulo = t ? t[1].replace(/\s+/g, ' ').trim() : '';

  const texto = html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<(header|nav|footer)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();

  let motivo = '';
  if (item.json.error) motivo = 'Error de conexión: ' + (item.json.error.message || 'sin detalle');
  else if (status >= 400) motivo = 'HTTP ' + status;
  else if (/request is being verified|One moment, please/i.test(html)) motivo = 'Bloqueada por la verificación anti-bot del hosting';
  else if (texto.length < 300) motivo = 'Texto insuficiente (' + texto.length + ' caracteres)';

  salida.push({ json: {
    url: origen.url, categoria: origen.categoria, titulo,
    texto, caracteres: texto.length, valido: motivo === '', motivo
  }});
});

return salida;
